// pluss::tils::format against the recorded {fmt} oracle (format_parity_golden.inc, generated by
// tools/format_parity_gen.cpp), plus the engine paths that share its grammar: writef/writelnf and join.
#include <pluss/tils/kit/output.h>

#include <cstdint>
#include <cstdio>
#include <iostream>
#include <limits>
#include <map>
#include <sstream>
#include <string>
#include <variant>
#include <vector>

namespace {

struct IntCase { const char* pat; long long v; const char* want; };
struct UIntCase { const char* pat; unsigned long long v; const char* want; };
struct DoubleCase { const char* pat; double v; const char* want; };
struct FloatCase { const char* pat; float v; const char* want; };
struct StringCase { const char* pat; const char* v; const char* want; };
struct BoolCase { const char* pat; bool v; const char* want; };
struct CharCase { const char* pat; char v; const char* want; };
struct PatternCase { const char* pat; const char* args; const char* want; };

#include "format_parity_golden.inc"

int failures = 0;
std::size_t checked = 0;
std::map<std::string, int> failed_in;

void report(const char* what, const std::string& pat, const std::string& got, const std::string& want) {
  ++failures;
  if (++failed_in[what] <= 400) std::cerr << "FAIL " << what << "  pattern=" << pat << "  got=[" << got << "]  want=[" << want << "]\n";
}

template <class Case>
void run(const char* what, const Case* cases, std::size_t n) {
  for (std::size_t i = 0; i < n; ++i) {
    ++checked;
    std::string got;
    try { got = pluss::tils::format(pluss::tils::runtime_format(cases[i].pat), cases[i].v); }
    catch (const std::exception& e) { got = std::string("<throws: ") + e.what() + ">"; }
    if (got != cases[i].want) report(what, cases[i].pat, got, cases[i].want);
  }
}
#define RUN(table, name) run(name, table, sizeof(table) / sizeof(table[0]))

using Arg = std::variant<long long, double, std::string>;

std::vector<Arg> parse_args(const std::string& src) {
  std::vector<Arg> out;
  std::istringstream is(src);
  std::string tok;
  while (is >> tok) {
    const std::string body = tok.substr(2);
    if (tok[0] == 'i') out.emplace_back(std::stoll(body));
    else if (tok[0] == 'd') out.emplace_back(std::stod(body));
    else out.emplace_back(body);
  }
  return out;
}

std::string call_format(const std::string& pat, const std::vector<Arg>& a) {
  const pluss::tils::runtime_format rt{pat};
  auto vis = [&](auto&&... xs) { return pluss::tils::format(rt, xs...); };
  switch (a.size()) {
    case 1: return std::visit(vis, a[0]);
    case 2: return std::visit([&](auto&& x, auto&& y) { return pluss::tils::format(rt, x, y); }, a[0], a[1]);
    case 3: return std::visit([&](auto&& x, auto&& y, auto&& z) { return pluss::tils::format(rt, x, y, z); }, a[0], a[1], a[2]);
    default: return "<unsupported arity>";
  }
}

void check(const std::string& got, const std::string& want, const char* what) {
  ++checked;
  if (got != want) report(what, what, got, want);
}

}  // namespace

int main() {
  RUN(kInt, "int");
  RUN(kUInt, "uint64");
  RUN(kDouble, "double");
  RUN(kFloat, "float");
  RUN(kString, "string");
  RUN(kBool, "bool");
  RUN(kChar, "char");
  for (const auto& c : kPattern) {
    ++checked;
    std::string got;
    try { got = call_format(c.pat, parse_args(c.args)); } catch (const std::exception& e) { got = std::string("<throws: ") + e.what() + ">"; }
    if (got != c.want) report("pattern", c.pat, got, c.want);
  }

  // the same grammar through OutputEngine
  {
    std::ostringstream os;
    pluss::tils::OutputEngine out(os);
    out.writelnf("{:>6.2f}|{:<5}|{:^7}|{:#x}", 3.14159, "ab", true, 255);
    check(os.str(), "  3.14|ab   | true  |0xff\n", "OutputEngine::writelnf");
  }
  // call-level PrintOptions keep working next to a spec: grouping / decimals fill in what the spec leaves unsaid,
  // and width / truncate / case apply to the piece
  {
    const auto grouped = pluss::tils::PrintOptions{}.fixed(2).grouped(',');
    check(pluss::tils::format("{:>10}", 25400L, grouped), "    25,400", "options + spec (int)");
    check(pluss::tils::format("{:>16}", 304800.25, grouped), "      304,800.25", "options + spec (float)");
    check(pluss::tils::format("[{}]", "hi", pluss::tils::PrintOptions{.align = pluss::tils::Align::Right, .width = 6}), "[    hi]", "call width, empty spec");
    check(pluss::tils::format("{}", "a-very-long-service-name", pluss::tils::PrintOptions{.truncate = 12}), "a-very-long\xE2\x80\xA6", "call truncate");
    check(pluss::tils::format("{}", "hello", pluss::tils::PrintOptions{.case_transform = pluss::tils::CaseXf::Upper}), "HELLO", "call case");
    check(pluss::tils::format("{:6}", "ab", pluss::tils::PrintOptions{.case_transform = pluss::tils::CaseXf::Upper}), "AB    ", "call case + spec width");
  }
  // print / println to a stream and to a C FILE*
  {
    std::ostringstream os;
    pluss::tils::print(os, "{}-{:03d}", "a", 7);
    pluss::tils::println(os, "|{:.1f}", 2.25);
    check(os.str(), "a-007|2.2\n", "print/println stream");
    std::FILE* f = std::tmpfile();
    pluss::tils::print(f, "x={:>4}", 5);
    std::rewind(f);
    char buf[16] = {};
    const std::size_t got = std::fread(buf, 1, sizeof buf - 1, f);
    std::fclose(f);
    check(std::string(buf, got), "x=   5", "print FILE*");
  }
  // join and trailing PrintOptions
  check(pluss::tils::join(std::vector<int>{1, 2, 3}, ", "), "1, 2, 3", "join ints");
  check(pluss::tils::join(std::vector<std::string>{"a", "b"}, "-"), "a-b", "join strings");
  check(pluss::tils::join(std::vector<int>{}, ", "), "", "join empty");
  check(pluss::tils::format("{} {}", 1, "x"), "1 x", "format plain");
  check(pluss::tils::OutputEngine::format("{:>4}|{:<4}|", 7, "ab"), "   7|ab  |", "OutputEngine::format (static)");
  {
    pluss::tils::OutputEngine engine;
    check(engine.format("{:03d}", 5), "005", "engine.format");
    check(engine.join(std::vector<int>{4, 5}, "+"), "4+5", "engine.join");
  }
  // malformed grammar throws instead of printing garbage
  for (const char* bad : {"{:q}", "{:.}", "{:*}", "{:{}", "{:5<<}"}) {
    ++checked;
    bool threw = false;
    try { (void)pluss::tils::format(pluss::tils::runtime_format(bad), 1); } catch (const pluss::Error&) { threw = true; }  // always a pluss::Error
    if (!threw && std::string(bad) != "{:{}" ) report("malformed", bad, "<no throw>", "<throws>");
  }

  for (const auto& [k, n] : failed_in) std::cerr << "  " << k << ": " << n << " failures\n";
  std::cout << "format parity: " << checked << " checks, " << failures << " failures\n";
  return failures == 0 ? 0 : 1;
}
